INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Einrichtung IT-Arbeitsplätze > Vorbereitung Abnahme Produkte & Leistungen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Kann die Abnahme von Produkten und Leistungen ohne vorherige Prüfung erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Prüfung sichert Qualität und Funktion"}, {"text": "Ja", "correct": false, "because": "Ohne Prüfung riskant"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der Vorbereitung der Abnahme immer Abnahmekriterien definiert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Kriterien sind Grundlage der Bewertung"}, {"text": "Nein", "correct": false, "because": "Definition ist Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Dokumentation der Abnahme von Produkten und Leistungen optional?', 2, '[{"text": "Nein", "correct": true, "because": "Dokumentation dient als Nachweis"}, {"text": "Ja", "correct": false, "because": "Nachvollziehbarkeit erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Abnahmeprüfungen ohne Beteiligung des Kunden durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Kundenbeteiligung ist oft vertraglich vorgeschrieben"}, {"text": "Ja", "correct": false, "because": "Kunde prüft Akzeptanz"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Vorbereitung der Abnahme unabhängig von den Vertragsbedingungen?', 2, '[{"text": "Nein", "correct": true, "because": "Vertrag definiert Rahmenbedingungen"}, {"text": "Ja", "correct": false, "because": "Vertrag ist maßgeblich"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Vorbereitung der Abnahme am wichtigsten?', 3, '[{"text": "Definition der Abnahmekriterien", "correct": true, "because": "Legt Bewertungsgrundlage fest"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch, nicht funktional"}, {"text": "Liefertermin", "correct": false, "because": "Logistisch, nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument dient als Grundlage für die Abnahme?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Rechnung", "correct": false, "because": "Finanzdokument"}, {"text": "Benutzerhandbuch", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird bei der Abnahmeprüfung oft geprüft?', 2, '[{"text": "Funktionalität", "correct": true, "because": "Sichert Erfüllung der Anforderungen"}, {"text": "Verpackung", "correct": false, "because": "Sekundär"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist typischerweise an der Abnahme beteiligt?', 3, '[{"text": "Kunde", "correct": true, "because": "Bewertet und akzeptiert"}, {"text": "Lieferant", "correct": false, "because": "Stellt bereit, prüft nicht"}, {"text": "Logistikdienst", "correct": false, "because": "Nur Transport"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptziel der Abnahmevorbereitung?', 2, '[{"text": "Qualitätssicherung", "correct": true, "because": "Gewährleistet Vertragsgemäßheit"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Vorbereitung der Abnahme?', 4, '[{"text": "Kriterien definieren", "correct": true, "because": "Grundlage der Prüfung"}, {"text": "Prüfplan erstellen", "correct": true, "because": "Strukturiert Ablauf"}, {"text": "Kunden informieren", "correct": true, "because": "Beteiligung sicherstellen"}, {"text": "Farbauswahl treffen", "correct": false, "because": "Ästhetisch, nicht funktional"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien werden bei der Abnahme geprüft?', 3, '[{"text": "Funktionalität", "correct": true, "because": "Erfüllung der Anforderungen"}, {"text": "Leistung", "correct": true, "because": "Effizienz des Systems"}, {"text": "Sicherheit", "correct": true, "because": "Schutz gewährleisten"}, {"text": "Verpackungsdesign", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Abnahmevorbereitung auftreten?', 3, '[{"text": "Unklare Kriterien", "correct": true, "because": "Erschwert Bewertung"}, {"text": "Fehlende Dokumentation", "correct": true, "because": "Kein Nachweis"}, {"text": "Kundenunzufriedenheit", "correct": true, "because": "Bei mangelhafter Vorbereitung"}, {"text": "Geringe Lautstärke", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Dokumente sind für die Abnahmevorbereitung relevant?', 4, '[{"text": "Pflichtenheft", "correct": true, "because": "Definiert Anforderungen"}, {"text": "Abnahmeprotokoll", "correct": true, "because": "Dokumentiert Ergebnisse"}, {"text": "Vertrag", "correct": true, "because": "Rechtliche Grundlage"}, {"text": "Rechnung", "correct": false, "because": "Finanzdokument"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gute Abnahmevorbereitung?', 3, '[{"text": "Qualitätssicherung", "correct": true, "because": "Erfüllt Standards"}, {"text": "Kundenzufriedenheit", "correct": true, "because": "Erwartungen erfüllt"}, {"text": "Reibungsloser Übergang", "correct": true, "because": "Minimiert Probleme"}, {"text": "Geringere Kosten", "correct": false, "because": "Nicht primär"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Abnahmekriterien sind bei der Vorbereitung essenziell. b) Die Abnahme kann ohne Kundenbeteiligung erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kriterien ja, Kunde nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Pflichtenheft dient als Grundlage für die Abnahme. b) Dokumentation ist bei der Abnahme optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflichtenheft ja, Dokumentation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Funktionalität wird bei der Abnahme geprüft. b) Vertragsbedingungen sind für die Abnahme irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktionalität ja, Vertrag relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Abnahmevorbereitung sichert die Qualität. b) Ein Prüfplan ist bei der Abnahme überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität ja, Prüfplan hilfreich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kunden sind bei der Abnahme beteiligt. b) Abnahmeprüfungen können ohne Kriterien erfolgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kunde ja, Kriterien nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

